"""Reproduce DiME teaching SVGs; measured result values from course PDF Table 1."""
from pathlib import Path
from html import escape
out=Path(__file__).resolve().parents[1]/'public/figures/dime'
out.mkdir(parents=True,exist_ok=True)
def text(x,y,s,size=19):
    return f'<text x="{x}" y="{y}" font-size="{size}">{escape(s)}</text>'
def box(x,y,w,a,b,color='#ddd9fa'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="86" rx="12" fill="{color}" stroke="#71849a"/>'+text(x+14,y+32,a)+text(x+14,y+62,b,16)
def arrow(x,y,a,b):
    return f'<path d="M{x} {y} L{a} {b}" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'
def svg(name,title,desc,body,h=440):
    (out/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 940 {h}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">{escape(desc)}</desc><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#53677d"/></marker></defs><rect width="940" height="{h}" rx="18" fill="#f3f6fb"/><g font-family="Arial,sans-serif" fill="#17304b">'+text(28,43,title,25)+body+'</g></svg>')
svg('problem','01 / An explanation must satisfy several goals','Three complementary goals, not measurements.',box(30,120,260,'Flip the prediction','Target: opposite decision','#ffe6cb')+box(340,120,260,'Preserve this input','Keep identity and context','#d4eee7')+box(650,120,260,'Remain plausible','Use a learned face prior')+text(30,290,'Tiny invisible perturbation: can flip a label without a visible explanation.',19)+text(30,332,'Entirely different face: can be plausible without explaining this person.',19)+text(30,404,'Schematic goals. Multiple plausible edits can expose different associations.',18))
svg('training','02 / Learn a prior; freeze it to explain a classifier','Training and inference paths use the same learned diffusion model.',box(30,100,260,'Training images','CelebA faces; no labels','#d4eee7')+arrow(300,143,335,143)+box(345,100,250,'Train DDPM','Learn reverse transitions')+arrow(605,143,640,143)+box(650,100,260,'Face image prior','Trained DDPM weights')+box(30,290,260,'Query + target label','Image state changes','#d4eee7')+arrow(300,333,335,333)+box(345,290,250,'Frozen DDPM','Proposes image states')+arrow(605,333,640,333)+box(650,290,260,'Frozen classifier','Input gradients guide edits','#ffe6cb')+text(30,432,'Training updates generator weights. Explanation updates only image state.',18)+text(30,470,'Classifier training is separate; the evaluation oracle is separate again.',18),505)
body=text(30,91,'zₜ = √αₜ × image + √(1 − αₜ) × noise     (paper αₜ is cumulative)',20)
for i,(a,b,c) in enumerate([('αₜ = 0.81','0.90 × image','0.436 × noise'),('αₜ = 0.64','0.80 × image','0.60 × noise'),('αₜ = 0.25','0.50 × image','0.866 × noise')]):
 x=30+i*310
 body+=box(x,140,260,a,b,'#d4eee7')+text(x+14,258,c,19)
body+=text(30,325,'Each state remains an image-shaped tensor: 128 × 128 × 3.',20)+text(30,366,'Increasing corruption weakens information about the original photograph.',18)+text(30,409,'Teaching noise levels; not the experimental schedule. No compressed code.',18)
svg('representation','03 / The representation is a noisy image','Three illustrative cumulative signal levels and their coefficients.',body)
svg('architecture','04 / Clean guidance steers a noisy transition','Full unconditional rollout feeds clean-image loss; scaled gradient shifts reverse mean.',box(30,100,260,'A · Current state zₜ','128 × 128 × 3','#d4eee7')+arrow(300,143,335,143)+box(345,100,250,'B · Full DDPM rollout','zₜ → … → clean xₜ')+arrow(605,143,640,143)+box(650,100,260,'C · Class + proximity','xₜ, target y, reference x','#ffe6cb')+arrow(780,196,780,255)+box(650,265,260,'D · Transfer gradient','ĝz = gx / √αₜ','#ffe6cb')+arrow(640,308,605,308)+box(345,265,250,'E · Guided transition','Mean μ − Σ ĝz')+arrow(470,361,470,415)+box(345,425,250,'Carry zₜ₋₁ forward','Sample; repeat at t − 1','#d4eee7')+'<path d="M160 196 L160 308 L335 308" fill="none" stroke="#53677d" stroke-width="3" marker-end="url(#a)"/>'+text(30,365,'DDPM gives μ and Σ',17)+text(30,555,'B uses repeated forward evaluations. No backpropagation through that rollout.',18)+text(30,590,'Functional schematic; optional direct noisy-state ℓ₁ guidance omitted here.',18),620)
svg('numbers','05 / A scalar trace through the same boxes','Synthetic example, not a trained model. Optional direct L1 term omitted.',box(30,95,260,'A · Corrupt x = 0.8','α = 0.64; ε = 0.2','#d4eee7')+arrow(300,138,335,138)+box(345,95,250,'A → B · zₜ = 0.76','Run clean rollout')+arrow(605,138,640,138)+box(650,95,260,'C · Assume gx = 0.4','Combined clean gradient','#ffe6cb')+box(30,260,260,'D · ĝz = 0.5','0.4 / √0.64','#ffe6cb')+arrow(300,303,335,303)+box(345,260,250,'E · Mean = 0.68','0.70 − 0.04 × 0.5')+arrow(605,303,640,303)+box(650,260,260,'E · Sample = 0.70','0.68 + √0.04 × 0.1','#d4eee7')+text(30,408,'Σ = 0.04 is variance. The fresh noise draw uses standard deviation √Σ = 0.2.',18))
svg('steps','06 / An outer trajectory with inner look-ahead rollouts','Noisy states move horizontally; clean previews refresh their guidance.',box(30,100,260,'Outer state z₃','Carry the noisy image','#d4eee7')+arrow(300,143,335,143)+box(345,100,250,'Outer state z₂','Carry the noisy image','#d4eee7')+arrow(605,143,640,143)+box(650,100,260,'Outer state z₁','Next step ends clean','#d4eee7')+arrow(160,196,160,255)+arrow(470,196,470,255)+arrow(780,196,780,255)+box(30,265,260,'3-step clean rollout','x₃ → new guidance')+box(345,265,250,'2-step clean rollout','x₂ → new guidance')+box(650,265,260,'1-step clean rollout','x₁ → new guidance')+text(30,402,'Each preview guides the transition leaving its own outer state.',19)+text(30,442,'Three-step schematic. The experiment starts at τ = 60, not 3.',18),475)
body=text(30,87,'CelebA · Smile · 128 × 128 · successful counterfactuals · FID ↓',18)
for i,(label,val,color) in enumerate([('DiVE',29.4,'#73859d'),('DiVE100',36.8,'#73859d'),('DiME',3.17,'#168373')]):
 y=115+i*75
 body+=text(30,y+27,label)+f'<rect x="220" y="{y}" width="{val*16}" height="38" rx="5" fill="{color}"/>'+text(230+val*16,y+27,str(val))
body+=text(220,361,'0',16)+text(380,361,'10',16)+text(540,361,'20',16)+text(700,361,'30',16)+text(30,408,'Table 1 values. Different flip rates mean different successful subsets.',18)
svg('results','07 / Reported image-distribution quality','Smile FID: DiVE 29.4, DiVE100 36.8, DiME 3.17. Lower is better.',body)
svg('correlation','08 / Compare correlation patterns, not just edit counts','Toy CD over two attributes: absolute differences sum to 0.15.',box(30,100,260,'Dataset label pairs','Pearson correlations','#d4eee7')+arrow(300,143,335,143)+box(345,100,250,'c: 0.60 and −0.20','Ground-truth labels','#d4eee7')+box(30,270,260,'Original → explanation','Oracle attribute changes','#ffe6cb')+arrow(300,313,335,313)+box(345,270,250,'cᴹ: 0.50 and −0.15','Correlations of changes','#ffe6cb')+arrow(605,143,640,218)+arrow(605,313,640,238)+box(650,190,260,'Absolute differences','0.10 + 0.05 = 0.15')+text(30,413,'Synthetic two-attribute example. Dataset correlation is not causal proof.',18))
